"""Local browser page for checking camera framing before baseline calibration."""

PREVIEW_HTML = r"""<!doctype html>
<html lang="ko">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>바른 자세 기준 설정</title>
<style>
:root{color-scheme:dark;--bg:#142824;--card:#203b35;--mint:#78cbb5;--text:#f2f7f4;--muted:#a8c0b7;--danger:#ffb0a5}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui,"Malgun Gothic",sans-serif;min-height:100vh;display:grid;place-items:center;padding:20px}
main{width:min(100%,520px)}h1{font-size:22px;margin:0 0 6px}p{color:var(--muted);line-height:1.55;margin:7px 0 16px}
.card{background:var(--card);border:1px solid #36574e;border-radius:22px;padding:18px;box-shadow:0 14px 42px #08151166}
.token{display:flex;gap:8px;margin-bottom:14px}input{min-width:0;flex:1;border:1px solid #54736a;border-radius:12px;background:#142824;color:white;padding:12px;font-size:14px}
.frame{position:relative;aspect-ratio:4/3;background:#0b1815;border-radius:16px;overflow:hidden;display:grid;place-items:center}
#image{width:100%;height:100%;object-fit:cover;display:none}#empty{color:var(--muted);text-align:center;padding:22px}
.corners{position:absolute;inset:12% 18%;pointer-events:none;opacity:.8;background:linear-gradient(var(--mint),var(--mint)) left top/28px 2px no-repeat,linear-gradient(var(--mint),var(--mint)) left top/2px 28px no-repeat,linear-gradient(var(--mint),var(--mint)) right top/28px 2px no-repeat,linear-gradient(var(--mint),var(--mint)) right top/2px 28px no-repeat,linear-gradient(var(--mint),var(--mint)) left bottom/28px 2px no-repeat,linear-gradient(var(--mint),var(--mint)) left bottom/2px 28px no-repeat,linear-gradient(var(--mint),var(--mint)) right bottom/28px 2px no-repeat,linear-gradient(var(--mint),var(--mint)) right bottom/2px 28px no-repeat}
.guides{position:absolute;inset:0;pointer-events:none;display:flex;align-items:center;justify-content:center;flex-direction:column;opacity:.38}.head{width:52px;height:65px;border-radius:50%;background:#92aaa233;border:1px solid #b8d4c855}.body{width:132px;height:94px;border-radius:55% 55% 28% 28%;background:#92aaa222;border:1px solid #b8d4c844;border-top:0}.line{width:48%;border-top:1px dashed #d2eee399;margin-top:-54px}
.buttons{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}button{border:0;border-radius:12px;padding:12px 16px;background:#2c685c;color:white;font-weight:650;cursor:pointer}button.secondary{background:#35504a}button:disabled{opacity:.45;cursor:not-allowed}
#state{margin:13px 0 0;color:var(--mint);min-height:24px}#detail{font-size:13px;color:var(--muted);white-space:pre-wrap;word-break:break-word}
.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:14px}.metric{border:1px solid #45645b;background:#19332d;border-radius:12px;padding:10px}.metric span{display:block;color:var(--muted);font-size:12px}.metric b{display:block;margin-top:4px;font-size:16px;overflow-wrap:anywhere}.attention{color:#ffd08a!important}.normal{color:var(--mint)!important}.unavailable{color:var(--danger)!important}
.small{font-size:12px;margin:12px 0 0}.bad{color:var(--danger)!important}
</style>
</head>
<body><main><section class="card">
<h1>기준 자세를 설정해 주세요</h1>
<p>카메라를 눈높이에 두고 머리와 양쪽 어깨가 화면 안에 보이도록 앉으세요. 미리보기로 위치를 맞춘 뒤 캘리브레이션을 시작합니다.</p>
<div class="token"><input id="token" type="password" autocomplete="off" placeholder="P2 기기 토큰"></div>
<div class="frame"><img id="image" alt="웹캠 미리보기"><div id="empty">미리보기를 시작하면<br>웹캠 화면이 여기에 표시됩니다.</div><div class="corners"></div><div class="guides"><div class="head"></div><div class="body"></div><div class="line"></div></div></div>
<div class="buttons"><button id="preview">미리보기 시작</button><button id="calibrate" disabled>기준 자세 측정</button><button id="confirm" disabled>기준 저장</button><button id="monitor" disabled>자세 분석 시작</button><button id="monitorStop" class="secondary" disabled>분석 종료</button><button id="cancel" class="secondary" disabled>취소</button><button id="stop" class="secondary" disabled>미리보기 종료</button></div>
<div id="state">P2 서버의 카메라 영상을 표시합니다.</div><div id="detail"></div>
<div class="metrics"><div class="metric"><span>자세 상태</span><b id="posture">측정 전</b></div><div class="metric"><span>머리 상대 위치 변화량 (ΔH)</span><b id="delta">-</b></div><div class="metric"><span>현재 상태 지속 시간</span><b id="duration">-</b></div><div class="metric"><span>랜드마크 신뢰도</span><b id="confidence">-</b></div><div class="metric"><span>측정 상태 / 사유</span><b id="reason">-</b></div><div class="metric"><span>이번 세션 집중 시간</span><b id="focus">-</b></div><div class="metric"><span>경고 횟수</span><b id="warnings">-</b></div><div class="metric"><span>API 최신 갱신 시각</span><b id="updated">-</b></div></div>
<details><summary>GET /status 응답 원문</summary><pre id="rawStatus"></pre></details>
<p class="small">기준을 저장한 뒤 분석을 시작하세요. 기준보다 머리를 앞으로 이동한 자세를 5초 이상 유지하면 상태가 바뀌는지 확인할 수 있습니다. 상태 판정은 P1의 머리 상대 위치 기준이며 의학적 거북목 진단은 아닙니다.</p>
<p class="small">영상은 브라우저에만 스트리밍되며 서버에 저장하지 않습니다. 미리보기 사용 중에는 디버그와 카메라 미리보기가 켜집니다. 종료 버튼을 눌러 설정을 복구하세요.</p>
</section></main>
<script>
const api='/api/v1', tokenEl=document.querySelector('#token'), image=document.querySelector('#image'), empty=document.querySelector('#empty');
const stateEl=document.querySelector('#state'), detailEl=document.querySelector('#detail');
const previewBtn=document.querySelector('#preview'), calibrateBtn=document.querySelector('#calibrate'), confirmBtn=document.querySelector('#confirm'), monitorBtn=document.querySelector('#monitor'), monitorStopBtn=document.querySelector('#monitorStop'), cancelBtn=document.querySelector('#cancel'), stopBtn=document.querySelector('#stop');
const postureEl=document.querySelector('#posture'),deltaEl=document.querySelector('#delta'),durationEl=document.querySelector('#duration'),confidenceEl=document.querySelector('#confidence'),reasonEl=document.querySelector('#reason'),focusEl=document.querySelector('#focus'),warningsEl=document.querySelector('#warnings'),updatedEl=document.querySelector('#updated'),rawStatusEl=document.querySelector('#rawStatus');
let active=false, monitoring=false, calibrated=false, timer=0, statusTimer=0, imageUrl='', calibrationId='', previousSettings=null;
tokenEl.value=sessionStorage.getItem('p2_preview_token')||'';
function auth(){const t=tokenEl.value.trim();if(!t)throw new Error('기기 토큰을 입력해 주세요.');sessionStorage.setItem('p2_preview_token',t);return {'Authorization':'Bearer '+t};}
function requestId(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
async function request(path,options={}){const h=auth();if(options.body){h['Content-Type']='application/json';options.body=JSON.stringify(options.body)}const r=await fetch(api+path,{...options,headers:{...h,...(options.headers||{})},cache:'no-store'});if(!r.ok){let m='요청 실패 ('+r.status+')';try{const j=await r.json();m=j.error?.message||m}catch{}throw new Error(m)}return r.headers.get('content-type')?.includes('application/json')?r.json():r;}
function showError(e){stateEl.textContent=e.message||String(e);stateEl.classList.add('bad')}
async function frameLoop(){if(!active)return;try{const r=await fetch(api+'/preview/frame',{headers:auth(),cache:'no-store'});if(!r.ok){let m='프레임을 읽지 못했어요 ('+r.status+')';try{m=(await r.json()).error?.message||m}catch{}throw new Error(m)}const blob=await r.blob(), next=URL.createObjectURL(blob);image.src=next;image.style.display='block';empty.style.display='none';if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=next;stateEl.classList.remove('bad');}catch(e){showError(e)}if(active)timer=setTimeout(frameLoop,250)}
previewBtn.onclick=async()=>{try{stateEl.textContent='카메라 미리보기를 준비하고 있어요.';previousSettings=(await request('/settings')).settings;await request('/settings',{method:'PUT',body:{debug_mode:true,preview_stream_enabled:true}});active=true;previewBtn.disabled=true;calibrateBtn.disabled=false;stopBtn.disabled=false;frameLoop();}catch(e){showError(e)}};
calibrateBtn.onclick=async()=>{try{if(calibrationId){await request('/calibration/confirm',{method:'POST',body:{calibration_id:calibrationId,confirm:false,request_id:requestId()}});calibrationId=''}const r=await request('/calibration/start',{method:'POST',body:{duration_sec:8,request_id:requestId()}});calibrationId=r.calibration_id;calibrateBtn.disabled=true;cancelBtn.disabled=false;confirmBtn.disabled=true;stateEl.textContent='편안한 기준 자세를 유지해 주세요.';pollCalibration()}catch(e){showError(e)}};
async function pollCalibration(){if(!calibrationId)return;try{const r=await request('/calibration/preview?calibration_id='+encodeURIComponent(calibrationId));stateEl.textContent=r.state==='COLLECTING'?'기준 자세를 측정하고 있어요 · '+Math.round((r.progress||0)*100)+'%':r.state==='READY'?'측정 완료 · 기준을 확인한 뒤 저장하세요.':r.state==='FAILED'?'측정 실패 · 위치와 조명을 확인하고 다시 시도하세요.':r.state;detailEl.textContent=JSON.stringify(r.preview?.summary||r.preview||{},null,2);if(r.state==='READY'){confirmBtn.disabled=false;return}if(r.state==='FAILED'){calibrateBtn.disabled=false;return}setTimeout(pollCalibration,500)}catch(e){showError(e)}}
confirmBtn.onclick=async()=>{try{const r=await request('/calibration/confirm',{method:'POST',body:{calibration_id:calibrationId,confirm:true,request_id:requestId()}});stateEl.textContent=r.calibrated?'기준 자세를 저장했습니다. 이제 자세 분석을 시작할 수 있어요.':'기준 자세를 저장하지 못했어요. 다시 저장하거나 취소할 수 있어요.';detailEl.textContent=JSON.stringify(r.calibration||r,null,2);if(r.calibrated){calibrated=true;calibrationId='';confirmBtn.disabled=true;cancelBtn.disabled=true;calibrateBtn.disabled=false;monitorBtn.disabled=false}}catch(e){showError(e)}};
cancelBtn.onclick=async()=>{if(!calibrationId)return;try{await request('/calibration/confirm',{method:'POST',body:{calibration_id:calibrationId,confirm:false,request_id:requestId()}});calibrationId='';confirmBtn.disabled=true;cancelBtn.disabled=true;calibrateBtn.disabled=false;stateEl.textContent='캘리브레이션을 취소했습니다.';detailEl.textContent=''}catch(e){showError(e)}};
async function statusLoop(){if(!monitoring)return;try{const s=await request('/status'),p=s.posture||{},i=p.indicators?.head_relative_position||{},session=s.session;const names={normal:'정상',attention:'주의',unavailable:'측정 불가'},reasons={low_confidence:'인식 신뢰도 낮음',occluded:'가려짐',out_of_frame:'화면 밖',ear_not_detected:'귀 미검출',shoulder_not_detected:'어깨 미검출',invalid_geometry:'위치 확인 필요',not_calibrated:'기준 자세 없음',camera_disconnected:'카메라 연결 끊김'};postureEl.textContent=names[p.state]||p.state||'-';postureEl.className=p.state||'';deltaEl.textContent=i.delta==null?'측정 불가':Number(i.delta).toFixed(4);durationEl.textContent=(p.duration_sec??0)+'초';confidenceEl.textContent=Math.round((p.confidence||0)*100)+'%';reasonEl.textContent=p.reason?(reasons[p.reason]||p.reason):'정상 측정 중';focusEl.textContent=session?(session.focus_sec||0)+'초':'0초';warningsEl.textContent=session?(session.warning_count||0)+'회':'0회';updatedEl.textContent=p.updated_at||'-';rawStatusEl.textContent=JSON.stringify(s,null,2);}catch(e){showError(e)}if(monitoring)statusTimer=setTimeout(statusLoop,500)}
monitorBtn.onclick=async()=>{try{await request('/monitoring/start',{method:'POST',body:{request_id:requestId()}});monitoring=true;monitorBtn.disabled=true;monitorStopBtn.disabled=false;calibrateBtn.disabled=true;stateEl.textContent='자세 분석 중입니다. 기준 자세보다 머리를 앞으로 이동해 상태 변화를 확인하세요.';statusLoop()}catch(e){showError(e)}};
monitorStopBtn.onclick=async()=>{try{monitoring=false;clearTimeout(statusTimer);const r=await request('/monitoring/stop',{method:'POST',body:{request_id:requestId()}});monitorBtn.disabled=!calibrated;monitorStopBtn.disabled=true;calibrateBtn.disabled=false;stateEl.textContent='자세 분석을 종료했습니다.';detailEl.textContent=JSON.stringify(r.session_summary||r,null,2)}catch(e){showError(e)}};
stopBtn.onclick=async()=>{active=false;clearTimeout(timer);if(monitoring)await monitorStopBtn.onclick();if(calibrationId)await cancelBtn.onclick();try{if(previousSettings)await request('/settings',{method:'PUT',body:{debug_mode:previousSettings.debug_mode,preview_stream_enabled:previousSettings.preview_stream_enabled}})}catch(e){showError(e)}previewBtn.disabled=false;calibrateBtn.disabled=true;monitorBtn.disabled=true;monitorStopBtn.disabled=true;stopBtn.disabled=true;cancelBtn.disabled=true;confirmBtn.disabled=true;image.style.display='none';empty.style.display='block';stateEl.textContent='미리보기를 종료했습니다.';if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl='';};
</script></body></html>"""
